            if (keep) {
                ind.dataset.x = keep.x;
                ind.dataset.w = keep.w;
                ind.style.transform = `translateX(${keep.x}px)`;
                ind.style.width = keep.w + 'px';
            }
            psortMove(box, !!keep);
